def predict_cnn(image,sigma,weights,strength=.25,tile=64):
    a=np.asarray(image,np.float32);sigma=np.broadcast_to(np.asarray(sigma,np.float32),a.shape)
    if a.ndim!=2 or min(a.shape)<16 or not np.isfinite(a).all() or a.min()<0:raise ValueError('Finite nonnegative 2D magnitude image required')
    if not np.isfinite(sigma).all() or sigma.min()<0 or not 0<=strength<=1:raise ValueError('Invalid noise or strength')
    scale=max(float(np.percentile(a,99.7)),1e-8)
    if sigma.max()>scale*.15:raise ValueError('Noise estimate outside pilot range')
    if not sigma.any() or strength==0:return a.copy()
    normalized=a/scale;noise=sigma/scale;h,w=a.shape;out=np.empty_like(a);halo=8
    context=threadpool_limits(limits=2,user_api='blas') if threadpool_limits else nullcontext()
    with context:
        for y in range(0,h,tile):
            for x in range(0,w,tile):
                y0=max(0,y-halo);x0=max(0,x-halo);y1=min(h,y+tile+halo);x1=min(w,x+tile+halo)
                v=np.stack([normalized[y0:y1,x0:x1],noise[y0:y1,x0:x1]*10],axis=-1)
                for layer in range(6):
                    padded=np.pad(v,((1,1),(1,1),(0,0)),mode='reflect')
                    windows=np.lib.stride_tricks.sliding_window_view(padded,(3,3),axis=(0,1))
                    matrix=windows.transpose(0,1,3,4,2).reshape(-1,9*v.shape[-1])
                    v=(matrix@weights['w'+str(layer)]+weights['b'+str(layer)]).reshape(v.shape[0],v.shape[1],-1)
                    if layer<5:v=np.where(v>=0,v,.1*v)
                residual=v[...,0];yy=min(tile,h-y);xx=min(tile,w-x)
                crop=residual[y-y0:y-y0+yy,x-x0:x-x0+xx];sg=noise[y:y+yy,x:x+xx]
                correction=np.clip(-sg*crop,-3*sg,3*sg)
                out[y:y+yy,x:x+xx]=np.maximum(0,normalized[y:y+yy,x:x+xx]+strength*correction)*scale
    return out.astype(np.float32)



