@lru_cache(maxsize=1)
def trained_neural_weights():
    raw=base64.b64decode(_NEURAL_WEIGHTS_B64)
    if hashlib.sha256(raw).hexdigest()!=_NEURAL_WEIGHTS_SHA256:raise RuntimeError('Neural weight integrity check failed')
    with np.load(io.BytesIO(raw),allow_pickle=False) as data:return {key:data[key] for key in data.files}

def neural_noise_estimate(image):
    a=np.asarray(image,np.float32)
    if a.ndim!=2 or not np.isfinite(a).all() or a.min()<0:raise ValueError('Finite magnitude image required')
    high=float(np.percentile(a,99.7));span=high-float(a.min())
    if span<=0:return dict(sigma=0.,support=0.,status='original: constant image',method='tile high-pass MAD')
    hh=(a[:-1,:-1]-a[1:,:-1]-a[:-1,1:]+a[1:,1:])/2
    tissue=np.minimum.reduce([a[:-1,:-1],a[1:,:-1],a[:-1,1:],a[1:,1:]])>.08*high
    values=[];pixels=0
    for y in range(0,hh.shape[0],32):
        for x in range(0,hh.shape[1],32):
            v=hh[y:y+32,x:x+32][tissue[y:y+32,x:x+32]]
            if len(v)>=48:
                s=float(np.median(abs(v-np.median(v))))/.67448975
                if s>0:values.append(s);pixels+=len(v)
    support=min(1.,pixels/max(1,int(tissue.sum())))*min(1.,len(values)/4)
    sigma=float(np.median(values)) if values else 0.
    return dict(sigma=min(sigma,.15*span),support=float(support),valid_tiles=len(values),method='tissue tile high-pass MAD',
                status='estimate available; calibration required' if support>=.35 and sigma>0 else 'original: insufficient noise support')



def neural_restore_frame(image,strength=.25):
    a=np.asarray(image,np.float32)
    if a.ndim!=2 or min(a.shape)<16 or not np.isfinite(a).all() or a.min()<0:
        return a.copy(),{'status':'original: unsupported magnitude input'}
    if strength<=0:return a.copy(),{'status':'original: neural strength is zero'}
    estimate=neural_noise_estimate(a)
    if estimate['support']<.35 or estimate['sigma']<=0:return a.copy(),{'status':estimate['status']}
    scale=max(float(np.percentile(a,99.7)),1e-8)
    if estimate['sigma']>scale*.15:return a.copy(),{'status':'original: noise outside trained pilot range'}
    restored=predict_cnn(a,estimate['sigma'],trained_neural_weights(),strength)
    return restored,{'status':'processed','support':estimate['support'],'sigma':estimate['sigma']}


