@dataclass
class NoiseEstimate:
    sigma: np.ndarray
    confidence: float
    valid_tiles: int

def estimate_local_noise(image, tile=32):
    a=np.asarray(image,dtype=np.float32)
    if a.ndim!=2 or min(a.shape)<16 or not np.isfinite(a).all() or np.min(a)<0:
        raise ValueError('Expected a finite, nonnegative native 2D magnitude image of at least 16×16 pixels')
    high=float(np.percentile(a,99.5));extent=float(np.max(a)-np.min(a))
    if extent<=0 or high<=0:return NoiseEstimate(np.zeros_like(a),0.,0)
    # Unit-energy diagonal high-pass; robust MAD estimates high-SNR magnitude noise.
    # No assumption that zero-filled air is a sampled Rayleigh background.
    hh=(a[:-1,:-1]-a[1:,:-1]-a[:-1,1:]+a[1:,1:])/2
    minimum=np.minimum.reduce([a[:-1,:-1],a[1:,:-1],a[:-1,1:],a[1:,1:]])
    tissue=minimum>.08*high
    rows=(hh.shape[0]+tile-1)//tile;cols=(hh.shape[1]+tile-1)//tile
    grid=np.full((rows,cols),np.nan,dtype=np.float32);counts=[]
    for y in range(rows):
        for x in range(cols):
            v=hh[y*tile:(y+1)*tile,x*tile:(x+1)*tile];mask=tissue[y*tile:(y+1)*tile,x*tile:(x+1)*tile];values=v[mask]
            # Sample air only if it actually contains measured, nonzero noise.
            # A zero-filled background is not evidence of zero physical noise.
            region=a[y*tile:min((y+1)*tile,a.shape[0]-1),x*tile:min((x+1)*tile,a.shape[1]-1)]
            positive=minimum[y*tile:(y+1)*tile,x*tile:(x+1)*tile]>0
            observed=v[positive]
            divisor=.67448975
            if len(observed)>=48:
                raw_mad=float(np.median(np.abs(observed-np.median(observed))))
                if raw_mad>0 and float(np.median(region[positive]))/(raw_mad/.67448975)<2.4:
                    values=observed
                    # MAD of the unit-energy HH of independent Rayleigh samples:
                    # 0.438 sigma (fixed-seed calibration, independent of MRI tests).
                    divisor=.438
            if len(values)<48:continue
            mad=float(np.median(np.abs(values-np.median(values))))/divisor
            if mad>0 and np.isfinite(mad):grid[y,x]=mad;counts.append(len(values))
    valid=np.isfinite(grid);n=int(valid.sum())
    if n==0:return NoiseEstimate(np.zeros_like(a),0.,0)
    # Fill unobserved tiles from nearest observed tissue, then interpolate smoothly.
    nearest=ndi.distance_transform_edt(~valid,return_distances=False,return_indices=True);grid=grid[tuple(nearest)]
    median=float(np.median(grid));grid=np.clip(grid,.25*median,3*median)
    grid=ndi.gaussian_filter(grid,.7,mode='nearest')
    yy=(np.arange(a.shape[0])+.5)/tile-.5;xx=(np.arange(a.shape[1])+.5)/tile-.5
    Y,X=np.meshgrid(yy,xx,indexing='ij');sigma=ndi.map_coordinates(grid,[Y,X],order=1,mode='nearest').astype(np.float32)
    confidence=float(min(1.,sum(counts)/max(1,int(tissue.sum())))*min(1.,n/4))
    return NoiseEstimate(sigma,confidence,n)

def texture_noise(image):
    estimate=estimate_local_noise(image)
    global_noise=estimate_noise(image)
    # A sampled air mode can support the estimate when reconstruction correlates
    # adjacent pixels. Never infer zero noise from a zero-filled background.
    if global_noise['method']=='mode' and global_noise['sigma']>0:
        air=np.asarray(image)[np.asarray(image)<=global_noise['bg_thr']]
        positive=air[air>0]
        if positive.size>=128 and positive.size>=.8*air.size:
            mad=float(np.median(np.abs(positive-np.median(positive))))
            ratio=float(np.median(positive))/max(mad,1e-12)
            if 1.7<ratio<3.8:
                estimate.sigma=np.maximum(estimate.sigma,global_noise['sigma'])
                estimate.confidence=max(estimate.confidence,.5)
    return estimate

def texture_denoise(image, sigma, amount):
    """Single-slice local Wiener shrinkage; no patch matching or magnitude debiasing.

    Keep a source contribution and shrink fine fluctuations less in structured
    neighborhoods. Sigma is an estimate, not a measurement of scanner noise.
    """
    a=np.asarray(image,dtype=np.float32)
    amount=float(np.clip(amount,0,1))
    if amount==0:return a.copy()
    variance=np.broadcast_to(np.asarray(sigma,dtype=np.float32),a.shape)**2
    mean=ndi.gaussian_filter(a,1.1,mode='reflect')
    local_var=np.maximum(ndi.gaussian_filter(a*a,1.1,mode='reflect')-mean*mean,0)
    # Local variance around a Gaussian mean contains less than the full noise variance.
    gain=np.clip(1-.88*variance/np.maximum(local_var,1e-12),0,1)
    candidate=mean+gain*(a-mean)
    return (a+amount*(candidate-a)).astype(np.float32)

def denoise_magnitude(image, strength='moderate', sigma=None, restore_detail=True):
    a=np.asarray(image,dtype=np.float32)
    estimate=texture_noise(a)
    if strength not in ('gentle','moderate'):raise ValueError('strength must be gentle or moderate')
    if sigma is None:
        sg=estimate.sigma
        if estimate.confidence<.35 or not np.any(sg>0):return a.copy(),{'status':'original: insufficient noise-estimation support','confidence':estimate.confidence}
    else:
        sg=np.broadcast_to(np.asarray(sigma,dtype=np.float32),a.shape).copy()
        if not np.isfinite(sg).all() or np.min(sg)<=0:raise ValueError('sigma must be positive and finite')
    # The exported DICOM may already have correlated/multi-coil noise or vendor
    # denoising. Do not assume single-coil Rician statistics or subtract 2*sigma².
    amount=.48 if strength=='gentle' else .72
    if not restore_detail:amount=.88
    out=texture_denoise(a,sg,amount)
    return out,{'status':'processed','strength':strength,'confidence':estimate.confidence,'valid_tiles':estimate.valid_tiles,
                'sigma_median':float(np.median(sg)),'noise_model':'local high-pass MAD estimate; no magnitude debiasing',
                'detail_restoration':bool(restore_detail),'method':'source-blended local Wiener shrinkage',
                'source':'oracle sigma' if sigma is not None else 'automatic local estimate'}


def estimate_noise(img):
    img = np.asarray(img, np.float32)
    mn, mx = float(img.min()), float(img.max())
    out = dict(sigma=0.0, fg=mx, p99=mx, bg_thr=0.0, method="none")
    if mx <= mn or img.shape[0] < 8 or img.shape[1] < 8:
        return out
    B = 4096
    h, _ = np.histogram(img, bins=B, range=(mn, mx))
    cdf = np.cumsum(h)
    p99 = mn + (np.searchsorted(cdf, 0.99 * cdf[-1]) + 1) * (mx - mn) / (B - 1)
    rng = p99 - mn
    lim = min(B - 1, int(rng * 0.2 / (mx - mn) * (B - 1)) + 1)
    sm = np.convolve(h[:lim + 1].astype(float), np.ones(13) / 13.0, mode="same")
    pk = int(np.argmax(sm))
    low_frac = h[:lim + 1].sum() / img.size
    sigma, method, bg_thr = 0.0, "mode", 0.0
    if low_frac > 0.05 and sm[pk] > 0:
        mode_off = pk * (mx - mn) / (B - 1)
        bg_thr = mn + mode_off * 3.2
        vals = img[img <= bg_thr]
        if vals.size:
            sigma = float(np.median(vals)) / 1.1774
            if not sigma > rng * 2e-4:
                sigma = 0.0
    if sigma == 0.0:
        method = "highpass"
        k = np.array([[1, -2, 1], [-2, 4, -2], [1, -2, 1]], np.float32)
        r = np.abs(ndi.convolve(img, k, mode="nearest"))[1:-1, 1:-1].ravel()
        sigma = float(np.quantile(r, 0.25)) / (0.3186 * 6) * 1.8
    fg_vals = img[img > mn + 0.15 * rng]
    out.update(sigma=sigma * (0.8 if method == "highpass" else 0.95),
               fg=float(np.median(fg_vals)) if fg_vals.size else mx, p99=float(p99), bg_thr=float(bg_thr), method=method)
    return out

_OFFS = [(1, 0), (0, 1), (2, 1), (3, 0), (0, 3), (3, 3), (-2, 2), (1, 3)]

def patch_baseline(img, bg_thr):
    img = np.asarray(img, np.float32)
    bg = (img <= bg_thr).astype(np.float32)
    bg = ndi.uniform_filter(bg, 3) > 0.999
    vals = []
    for dx, dy in _OFFS:
        sh = np.roll(np.roll(img, -dy, 0), -dx, 1)
        shm = np.roll(np.roll(bg, -dy, 0), -dx, 1)
        m = ndi.uniform_filter((img - sh) ** 2, 3)
        mask = bg & shm
        mask[:4, :] = mask[-4:, :] = False
        mask[:, :4] = mask[:, -4:] = False
        if mask.sum() > 50:
            vals.append(float(m[mask].mean()))
    return float(np.mean(vals)) if vals else 0.0

def presentation_field(frames):
    """Bounded image-derived shading estimate for display only, not prescan correction."""
    fields = []
    for frame in frames:
        a = np.asarray(frame, dtype=np.float32)
        finite = np.isfinite(a)
        if not finite.all() or a.ndim != 2 or min(a.shape) < 16:
            continue
        low, high = np.percentile(a, [1, 99])
        if high <= low:
            continue
        a = ndi.zoom(a, (64/a.shape[0], 64/a.shape[1]), order=1)
        signal = np.maximum(a - low, 0)
        mask = signal > .12 * (high - low)
        if mask.mean() < .10:
            continue
        # Very broad, mask-normalized log field: fine tissue interfaces are excluded.
        radius = max(a.shape) / 5.0
        weights = ndi.gaussian_filter(mask.astype(np.float32), radius)
        logs = ndi.gaussian_filter(np.log(np.maximum(signal, .12*(high-low))) * mask, radius)
        field = logs / np.maximum(weights, 1e-6)
        reference = float(np.median(field[mask]))
        gain = np.exp(np.clip(.35*(reference-field), np.log(.85), np.log(1.18)))
        gain = 1 + (gain-1)*np.clip((weights-.05)/.20, 0, 1)
        small = ndi.zoom(gain, (32/a.shape[0], 32/a.shape[1]), order=1)
        fields.append(small)
    if not fields:
        return None
    return dict(rows=32, cols=32, gain=np.round(np.median(fields, axis=0), 4).ravel().tolist())


def signal_balance_gain(frames, strength=.5):
    """Shared, bounded N4 field from representative magnitude frames; no histogram matching.

    Display only. A common field avoids independent slice normalization flicker.
    Discontinuous station seams require registered overlap data and are not inferred here.
    """
    strength = float(strength)
    if not np.isfinite(strength) or not 0 <= strength <= 1:
        raise ValueError("Signal Balance strength must be between zero and one")
    shape = np.asarray(frames[0]).shape
    if strength == 0:
        return np.ones(shape, np.float32), "off"
    if len(shape) != 2 or min(shape) < 32:
        return np.ones(shape, np.float32), "unsupported image dimensions"
    try:
        import SimpleITK as sitk
    except ImportError:
        raise RuntimeError("Signal Balance needs SimpleITK. Deploy the updated requirements.txt as well as main.py.")
    fields=[]
    for index in np.unique(np.linspace(0,len(frames)-1,min(3,len(frames))).astype(int)):
        a=np.asarray(frames[index],np.float32)
        if a.shape != shape or not np.isfinite(a).all() or a.min()<0:
            return np.ones(shape,np.float32), "unsupported signed or nonfinite pixels"
        high=float(np.percentile(a,99.5))
        if high<=0 or np.ptp(a)<high*1e-6:
            continue
        # Otsu excludes air. Keep positive low-intensity tissue; avoid hole filling into air.
        image=sitk.GetImageFromArray(np.maximum(a/high,1e-6))
        mask=sitk.OtsuThreshold(image,0,1,128)
        mask_array=sitk.GetArrayFromImage(mask).astype(bool)&(a>high*.01)
        if mask_array.sum()<256 or mask_array.mean()<.03:
            continue
        mask=sitk.GetImageFromArray(mask_array.astype(np.uint8))
        shrink=max(1,int(max(shape)/128))
        corrector=sitk.N4BiasFieldCorrectionImageFilter()
        corrector.SetNumberOfThreads(2)
        corrector.SetMaximumNumberOfIterations([30,20])
        corrector.SetConvergenceThreshold(.001)
        corrector.Execute(sitk.Shrink(image,[shrink]*2),sitk.Shrink(mask,[shrink]*2))
        logfield=sitk.GetArrayFromImage(corrector.GetLogBiasFieldAsImage(image))
        logfield-=np.median(logfield[mask_array])
        if np.isfinite(logfield).all():
            fields.append(logfield)
    if not fields:
        return np.ones(shape,np.float32), "insufficient tissue support"
    # ±50% maximum multiplicative change; no local texture or edge manipulation.
    field=np.median(np.stack(fields),axis=0)
    gain=np.exp(np.clip(-strength*field,np.log(2/3),np.log(1.5))).astype(np.float32)
    return gain, "N4 shared-field correction"


def series_info(frames):
    n = len(frames)
    idxs = sorted({int(np.clip(round((i + 0.5) / min(5, n) * n - 0.5), 0, n - 1)) for i in range(min(5, n))})
    sg, pb, fg, his, los = [], [], [], [], []
    for i in idxs:
        f = frames[i]
        nz = estimate_noise(f)
        sg.append(nz["sigma"]); fg.append(nz["fg"])
        pb.append(patch_baseline(f, nz["bg_thr"]) if nz["method"] == "mode" else 0.0)
        p005 = float(np.percentile(f, 0.5)); p995 = float(np.percentile(f, 99.5))
        fgm = f > (f.min() + 0.08 * (p995 - f.min()))
        hi = float(np.percentile(f[fgm], 99.7)) if fgm.mean() >= 0.03 else p995
        los.append(p005); his.append(hi)
    sigma = float(np.median(sg)); fgv = float(np.median(fg))
    lo = min(0.0, float(min(los)))
    hi = max(float(np.median(his)), lo + 1e-6)
    return dict(field=presentation_field([frames[i] for i in idxs]), sigma=sigma, pb=float(np.median(pb)), lo=lo, hi=hi, snr=(fgv / sigma if sigma > 0 else 100.0))

def bias_correct(d, strength, info):
    if strength <= 0:
        return d
    mask = (d > info["lo"] + 0.10 * (info["hi"] - info["lo"])).astype(np.float32)
    if mask.mean() < 0.05:
        return d
    s = max(d.shape) / 12.0
    num = ndi.gaussian_filter(d * mask, s); den = ndi.gaussian_filter(mask, s)
    est = np.where(den > 0.05, num / np.maximum(den, 1e-6), 0)
    gm = float(d[mask > 0].mean())
    gain = np.where(est > 0, np.clip(gm / np.maximum(est, 1e-6), 0.6, 1.8), 1.0) ** strength
    return d * gain.astype(np.float32)

def sharpen(d, sigma, s, info):
    if s<=0:return d.copy()
    fine=ndi.gaussian_filter(d,.7,mode='reflect')
    broad=ndi.gaussian_filter(d,1.4,mode='reflect')
    local_var=np.maximum(ndi.gaussian_filter(d*d,1.2,mode='reflect')-
                         ndi.gaussian_filter(d,1.2,mode='reflect')**2,0)
    variance=np.asarray(sigma,dtype=np.float32)**2
    reliability=np.clip((local_var-variance)/np.maximum(local_var+variance,1e-12),0,1)
    detail=.7*(d-fine)+.3*(fine-broad)
    boost=s*reliability*detail
    cap=max(info['hi']-info['lo'],1e-6)*.04*s
    out=d+np.clip(boost,-cap,cap)
    return np.clip(out,ndi.minimum_filter(d,3,mode='reflect'),ndi.maximum_filter(d,3,mode='reflect')).astype(np.float32)

def enhance_frame(frames, k, info, p):
    d0=np.asarray(frames[k],dtype=np.float32)
    if min(d0.shape)<16 or not np.isfinite(d0).all() or d0.min()<0:return d0.copy()
    estimate=texture_noise(d0)
    if estimate.confidence<.35 or not np.any(estimate.sigma>0):return d0.copy()
    sg=estimate.sigma
    # Same-slice processing avoids borrowing anatomy from a neighboring slice.
    # Retain a minimum source contribution; never threshold the residual into patches.
    preservation=.15+.20*np.clip(p.get('detail',70)/100,0,1)+.10*np.clip(p.get('grain',15)/100,0,1)
    amount=np.clip(p.get('denoise',55)/100,0,1)*(1-preservation)
    d=texture_denoise(d0,sg,amount)
    if p.get('shading',0)>0:d=bias_correct(d,p['shading']/100,info)
    return sharpen(d,sg,np.clip(p.get('sharpen',30)/100,0,1),info)


def pack_series(orig_frames, enh_frames=None):
    mn = min(float(f.min()) for f in orig_frames)
    mx = max(float(f.max()) for f in orig_frames)
    if enh_frames:
        mn = min(mn, min(float(f.min()) for f in enh_frames))
        mx = max(mx, max(float(f.max()) for f in enh_frames))
    if mx <= mn:
        mx = mn + 1.0
    scale = (mx - mn) / 65535.0

    def enc(f):
        u = np.clip(np.rint((f - mn) / scale), 0, 65535).astype("<u2")
        return base64.b64encode(zlib.compress(u.tobytes(), 3)).decode("ascii")

    items = []
    for i, f in enumerate(orig_frames):
        it = {"o": enc(f)}
        if enh_frames:
            it["e"] = enc(enh_frames[i])
        items.append(it)
    return dict(off=mn, scale=scale, items=items)

def unpack_frame(b64, rows, cols, off, scale):
    u = np.frombuffer(zlib.decompress(base64.b64decode(b64)), "<u2").reshape(rows, cols)
    return off + u.astype(np.float32) * scale

# ----------------------------------------------------------------------------------------------------------------
#  DICOM Parsing & Grouping Mechanics (Preserved with strict structural safety)
# ----------------------------------------------------------------------------------------------------------------
def _first(v, default=None):
    try:
        if v is None:
            return default
        if hasattr(v, "__len__") and not isinstance(v, (str, bytes)):
            return float(v[0]) if len(v) else default
        return float(v)
    except Exception:
        return default

def _floats(v, n):
    try:
        a = [float(x) for x in v]
        return a if len(a) == n else None
    except Exception:
        return None

def decode_pixels(ds):
    """Use pydicom's automatic decoder selection; retain source pixel data."""
    from pydicom.pixels import get_decoder
    uid = getattr(getattr(ds, "file_meta", None), "TransferSyntaxUID", None)
    if uid is None:
        raise RuntimeError("Missing DICOM TransferSyntaxUID; the encoding cannot be determined safely.")
    try:
        decoder = get_decoder(uid)
    except NotImplementedError as exc:
        raise RuntimeError(f"Unsupported DICOM transfer syntax: {uid.name} ({uid}).") from exc
    if not decoder.is_available:
        packages = {
            "1.2.840.10008.1.2.4.80": "pyjpegls>=1.2 (JPEG-LS)",
            "1.2.840.10008.1.2.4.81": "pyjpegls>=1.2 (JPEG-LS)",
            "1.2.840.10008.1.2.4.90": "pylibjpeg and pylibjpeg-openjpeg (JPEG 2000)",
            "1.2.840.10008.1.2.4.91": "pylibjpeg and pylibjpeg-openjpeg (JPEG 2000)",
        }
        needed = packages.get(str(uid), "the matching DICOM pixel decoder")
        raise RuntimeError(
            f"Decoder unavailable for {uid.name} ({uid}). Install {needed} on the hosting server "
            "using the updated requirements.txt, then rebuild/reboot the app. "
            "Re-uploading or repacking the ZIP will not install the decoder."
        )
    try:
        from pydicom.pixels import pixel_array
        return np.asarray(pixel_array(ds))
    except Exception as exc:
        raise RuntimeError(f"Pixel decoding failed for {uid.name} ({uid}): {exc}") from exc


def iter_modality_frames(ds):
    from pydicom.pixels import iter_pixels, get_decoder
    uid = getattr(getattr(ds, "file_meta", None), "TransferSyntaxUID", None)
    if uid is None:
        raise RuntimeError("Missing DICOM TransferSyntaxUID.")
    decoder = get_decoder(uid)
    if not decoder.is_available:
        decode_pixels(ds)  # Reuse the actionable decoder dependency message.
    nfr = int(getattr(ds, "NumberOfFrames", 1) or 1)
    slope = _first(getattr(ds, "RescaleSlope", None), 1.0)
    icpt = _first(getattr(ds, "RescaleIntercept", None), 0.0)
    count = 0
    original = getattr(ds,"_source_dataset",ds)
    source = original.filename if getattr(original, "_archive_owner", None) is not None else original
    frame_index=getattr(ds,"_source_frame",None)
    for arr in iter_pixels(source,indices=[frame_index] if frame_index is not None else None):
        if arr.ndim == 3 and arr.shape[-1] == 3:
            arr = arr[..., 0] * .299 + arr[..., 1] * .587 + arr[..., 2] * .114
        if arr.shape != (int(ds.Rows), int(ds.Columns)):
            raise RuntimeError(f"Unsupported pixel dimensions: {arr.shape}.")
        frame = np.asarray(arr, np.float32) * slope + icpt
        if not np.isfinite(frame).all():
            raise RuntimeError("Pixel data contains non-finite values.")
        count += 1
        yield frame
    if count != nfr:
        raise RuntimeError(f"Frame count mismatch: expected {nfr}, decoded {count}.")


def modality_frames(ds):
    return list(iter_modality_frames(ds))


def frame_count(s):
    return sum(max(1, int(getattr(d, "NumberOfFrames", 1) or 1)) for d in s["items"])


def payload_estimate(s, enhance=False):
    # Conservative transport estimate: quantised pixels, base64, JSON and optional enhanced copy.
    return frame_count(s) * s["rows"] * s["cols"] * 3 * (2 if enhance else 1)


def cine_series(s):
    # A timing tag may be constant on a static 3D acquisition. Presence is not motion.
    items=s["items"]
    if any(int(getattr(d,"NumberOfFrames",1) or 1)>1 or int(getattr(d,"NumberOfTemporalPositions",1) or 1)>1 for d in items):return True
    for name in ("TemporalPositionIdentifier","TriggerTime"):
        values={str(getattr(d,name)) for d in items if getattr(d,name,None) is not None}
        if len(values)>1:return True
    return False


def stream_pack_series(s, progress=None):
    count = frame_count(s)
    sample_indices = set(np.linspace(0, count-1, min(5, count), dtype=int).tolist())
    samples = []; mn = float("inf"); mx = -float("inf"); k = 0
    for ds in s["items"]:
        for f in iter_modality_frames(ds):
            mn = min(mn, float(f.min())); mx = max(mx, float(f.max()))
            if k in sample_indices: samples.append(f.copy())
            k += 1
            if progress and k % 10 == 0: progress(.5*k/count)
    if k != count or not samples:
        raise RuntimeError("Series frame count is inconsistent.")
    info = series_info(samples)
    del samples
    scale = (max(mx, mn+1.0)-mn)/65535.0
    items = []; k = 0; packed_bytes = 0
    for ds in s["items"]:
        for f in iter_modality_frames(ds):
            u = np.clip(np.rint((f-mn)/scale), 0, 65535).astype("<u2")
            encoded = base64.b64encode(zlib.compress(u.tobytes(),3)).decode("ascii")
            packed_bytes += len(encoded) + 16
            if packed_bytes > WORKSPACE_PAYLOAD_BUDGET:
                raise RuntimeError("Actual compressed series payload exceeds the embedded viewer capacity. This series was not partially loaded.")
            items.append({"o":encoded})
            k += 1
            if progress and k % 10 == 0: progress(.5+.5*k/count)
    return dict(off=mn, scale=scale, items=items), info, mn, mx


def plane_name(normal):
    k = int(np.argmax(np.abs(normal)))
    return ["Sagittal", "Coronal", "Axial"][k]

def geometry_of(ds):
    iop = _floats(getattr(ds, "ImageOrientationPatient", None) or [], 6)
    if iop:
        r, c = np.array(iop[:3]), np.array(iop[3:])
        n = np.cross(r, c)
    else:
        n = np.array([0.0, 0.0, 1.0])
    return n

def slice_position(ds, normal):
    ipp = _floats(getattr(ds, "ImagePositionPatient", None) or [], 3)
    return float(np.dot(ipp, normal)) if ipp else None


class DiffusionFrameView:
    """Metadata view retaining the original object and pixel frame index, without copying pixels."""
    def __init__(self, source, overrides, frame_index=None):
        self._source_dataset=source
        self._source_frame=frame_index
        self._overrides=overrides
    def __getattr__(self,name):
        if name in self._overrides:return self._overrides[name]
        return getattr(self._source_dataset,name)
    def __contains__(self,key):return key in self._source_dataset


def diffusion_metadata(ds,frame=None,shared=None):
    """Prefer frame-specific type/quantity metadata; b-value alone never identifies ADC."""
    scopes=[v for v in (frame,shared,ds) if v is not None]
    types=[];coded=[];bvalue=None;chosen_types=False;chosen_codes=False;code_scope=None
    for scope in scopes:
        local_types=[];local_codes=[]
        local_types.extend(str(v).upper() for v in getattr(scope,"ImageType",[]))
        local_types.extend(str(v).upper() for v in getattr(scope,"FrameType",[]))
        for item in getattr(scope,"MRImageFrameTypeSequence",[]):
            local_types.extend(str(v).upper() for v in getattr(item,"FrameType",[]))
        # Restrict traversal to quantity/derivation definitions, not referenced source images.
        for key in ("RealWorldValueMappingSequence","QuantityDefinitionSequence","DerivationCodeSequence"):
            for item in getattr(scope,key,[]):
                def codes(node,depth=0):
                    if depth>4:return
                    for attr in ("CodeMeaning","TextValue","LUTLabel","LUTExplanation"):
                        value=getattr(node,attr,None)
                        if value:local_codes.append(str(value).upper())
                    for attr in ("QuantityDefinitionSequence","ConceptNameCodeSequence","ConceptCodeSequence","MeasurementUnitsCodeSequence"):
                        for child in getattr(node,attr,[]):codes(child,depth+1)
                codes(item)
        if local_types and not chosen_types:types=local_types;chosen_types=True
        if local_codes and not chosen_codes:coded=local_codes;chosen_codes=True;code_scope=scope
        if bvalue is None:
            candidates=list(getattr(scope,"MRDiffusionSequence",[]))+[scope]
            for candidate in candidates:
                value=_first(getattr(candidate,"DiffusionBValue",None))
                if value is not None and np.isfinite(value) and value>=0:
                    bvalue=round(float(value),1);break
    if frame is not None and code_scope is not frame and "DIFFUSION" in types and "NONE" in types and "ADC" not in types:
        coded=[]
    structured=" ".join(types+coded)
    adc_pattern=r"(?:^|[^A-Z])ADC(?:$|[^A-Z])|APPARENT[ _-]*DIFFUSION[ _-]*COEFFICIENT"
    if re.search(adc_pattern,structured):return "ADC",None
    desc=" ".join(str(getattr(ds,k,"")) for k in ("SeriesDescription","ProtocolName")).upper()
    adc_name=bool(re.search(adc_pattern,desc))
    dwi_name=bool(re.search(r"DWI|DIFFUSION[ _-]*WEIGHTED|TRACE",desc))
    if adc_name and not dwi_name:return "ADC",None
    if any(v in ("DIFFUSION","TRACEW","TRACE","DIFFUSION_ISO") for v in types) or bvalue is not None:
        return "DWI",bvalue
    if dwi_name and not adc_name:return "DWI",bvalue
    return "",None


def diffusion_views(ds):
    if str(getattr(ds,"Modality","MR")).upper()!="MR":return [(ds,"",None)]
    n=int(getattr(ds,"NumberOfFrames",1) or 1)
    frames=getattr(ds,"PerFrameFunctionalGroupsSequence",[])
    shareds=getattr(ds,"SharedFunctionalGroupsSequence",[])
    shared=shareds[0] if shareds else None
    if n>1 and len(frames)==n:
        classified=[diffusion_metadata(ds,f,shared) for f in frames]
        # Ordinary cine/volume data keeps its existing streaming path.
        if any(kind for kind,_ in classified):
            result=[]
            for index,(frame,(kind,bvalue)) in enumerate(zip(frames,classified)):
                kind=kind or "UNCLASSIFIED"
                overrides={"NumberOfFrames":1,"InstanceNumber":index+1,"_diffusion_family":kind}
                if bvalue is not None:overrides["DiffusionBValue"]=bvalue
                for scope in (shared,frame):
                    if scope is None:continue
                    for seq,attrs in (("PlanePositionSequence",("ImagePositionPatient",)),("PlaneOrientationSequence",("ImageOrientationPatient",)),("PixelMeasuresSequence",("PixelSpacing","SliceThickness","SpacingBetweenSlices")),("PixelValueTransformationSequence",("RescaleSlope","RescaleIntercept")),("FrameVOILUTSequence",("WindowCenter","WindowWidth")),("MRImageFrameTypeSequence",("FrameType",))):
                        items=getattr(scope,seq,[])
                        if items:
                            for attr in attrs:
                                if hasattr(items[0],attr):overrides["ImageType" if attr=="FrameType" else attr]=getattr(items[0],attr)
                    mappings=getattr(scope,"RealWorldValueMappingSequence",None)
                    if mappings:overrides["RealWorldValueMappingSequence"]=mappings
                result.append((DiffusionFrameView(ds,overrides,index),kind,bvalue))
            return result
    kind,bvalue=diffusion_metadata(ds,shared=shared)
    if kind:
        return [(DiffusionFrameView(ds,{"_diffusion_family":kind},None),kind,bvalue)]
    return [(ds,"",None)]



def static_spatial_views(ds):
    """Expose enhanced static spatial frames while leaving cine/temporal objects intact."""
    n=int(getattr(ds,"NumberOfFrames",1) or 1)
    frames=getattr(ds,"PerFrameFunctionalGroupsSequence",[])
    if n<1 or len(frames)!=n or str(getattr(ds,"Modality","")).upper() not in ("MR","CT"):return None
    if int(getattr(ds,"NumberOfTemporalPositions",1) or 1)>1:return None
    shareds=getattr(ds,"SharedFunctionalGroupsSequence",[]);shared=shareds[0] if shareds else None
    temporal=set();views=[]
    for index,frame in enumerate(frames):
        for content in getattr(frame,"FrameContentSequence",[]):
            temporal.add(int(getattr(content,"TemporalPositionIndex",1) or 1))
        if len(temporal)>1:return None
        overrides={"NumberOfFrames":1,"InstanceNumber":index+1}
        for scope in (shared,frame):
            if scope is None:continue
            for seq,attrs in (("PlanePositionSequence",("ImagePositionPatient",)),("PlaneOrientationSequence",("ImageOrientationPatient",)),("PixelMeasuresSequence",("PixelSpacing","SliceThickness","SpacingBetweenSlices")),("PixelValueTransformationSequence",("RescaleSlope","RescaleIntercept")),("FrameVOILUTSequence",("WindowCenter","WindowWidth")),("MREchoSequence",("EffectiveEchoTime",)),("MRImageFrameTypeSequence",("FrameType",)),("CTImageFrameTypeSequence",("FrameType",))):
                items=getattr(scope,seq,[])
                if items:
                    for attr in attrs:
                        if hasattr(items[0],attr):overrides[{"FrameType":"ImageType","EffectiveEchoTime":"EchoTime"}.get(attr,attr)]=getattr(items[0],attr)
            mappings=getattr(scope,"RealWorldValueMappingSequence",None)
            if mappings:overrides["RealWorldValueMappingSequence"]=mappings
        view=DiffusionFrameView(ds,overrides,index)
        if not (_floats(getattr(view,"ImagePositionPatient",None),3) and _floats(getattr(view,"ImageOrientationPatient",None),6) and _floats(getattr(view,"PixelSpacing",None),2)):return None
        views.append(view)
    positions=[tuple(_floats(v.ImagePositionPatient,3)) for v in views]
    if len(set(positions))!=n:return None
    return [(view,"",None) for view in views]


def group_series(named_datasets):
    seen,groups=set(),{};dup=0
    for name,ds in named_datasets:
        sop=str(getattr(ds,"SOPInstanceUID","") or "")
        if sop:
            if sop in seen:dup+=1;continue
            seen.add(sop)
        views=diffusion_views(ds)
        if len(views)==1 and not views[0][1]:views=static_spatial_views(ds) or views
        for view,kind,bvalue in views:
            key=(str(getattr(ds,"StudyInstanceUID","")),str(getattr(ds,"SeriesInstanceUID","unknown")),int(ds.Rows),int(ds.Columns),kind,bvalue)
            groups.setdefault(key,[]).append(view)
    # Unknown objects within a known diffusion series must not enter a DWI or ADC stack.
    diffusion_parents={key[:4] for key in groups if key[4]}
    series=[]
    for (study,source_uid,rows,cols,kind,bvalue),lst in groups.items():
        a=lst[0]
        if not kind and (study,source_uid,rows,cols) in diffusion_parents:kind="UNCLASSIFIED"
        suffix=("ADC" if kind=="ADC" else "DWI"+(f" · b={bvalue:g}" if bvalue is not None else " · b unknown") if kind=="DWI" else "Diffusion · unclassified" if kind=="UNCLASSIFIED" else "")
        original_desc=str(getattr(a,"SeriesDescription","") or getattr(a,"ProtocolName","") or "Series")
        desc=original_desc+(" · "+suffix if suffix else "")
        # Virtual identity is internal; the original DICOM UID remains unmodified.
        uid=source_uid+("|"+kind+"|"+str(bvalue) if kind else "")
        if kind:
            lst=[DiffusionFrameView(d,{"SeriesDescription":desc,"_diffusion_family":kind},None) if not isinstance(d,DiffusionFrameView) else d for d in lst]
            for d in lst:d._overrides.update(SeriesDescription=desc,_diffusion_family=kind)
        num=int(_first(getattr(a,"SeriesNumber",None),0) or 0);normal=geometry_of(a);keyed=[]
        for ds in lst:
            position=slice_position(ds,normal)
            keyed.append((position if position is not None else float("inf"),int(_first(getattr(ds,"InstanceNumber",None),0) or 0),ds))
        keyed.sort(key=(lambda t:(t[0],t[1])) if all(k[0]!=float("inf") for k in keyed) else (lambda t:t[1]))
        series.append(dict(uid=uid,source_uid=source_uid,rows=rows,cols=cols,desc=desc,num=num,diffusion_family=kind,bvalue=bvalue,items=[k[2] for k in keyed],normal=normal,
                           label=f"#{num} {desc} · {rows}×{cols} · {sum(max(1,int(getattr(d,'NumberOfFrames',1) or 1)) for d in lst)} img"))
    series.sort(key=lambda s:(s["num"],0 if s.get("diffusion_family")=="DWI" else 1 if s.get("diffusion_family")=="ADC" else 2,-(s.get("bvalue") if s.get("bvalue") is not None else -1),s["desc"]))
    return series,dup


def read_zip(zbytes, max_member=400 * 1024 * 1024, progress=None):
    import pydicom
    out, skipped = [], Counter()
    with zipfile.ZipFile(io.BytesIO(zbytes)) as z:
        infos = [i for i in z.infolist() if not i.is_dir()]
        if sum(i.file_size for i in infos) > 2*1024*1024*1024:
            raise RuntimeError("Archive exceeds the current temporary disk import budget (2 GiB). Export a smaller study selection; no images have been partially loaded.")
        archive_owner = tempfile.TemporaryDirectory(prefix="dicom-study-")
        for n, info in enumerate(infos):
            base = info.filename.rsplit("/", 1)[-1]
            if "__MACOSX" in info.filename or base.startswith("."):
                continue
            if info.file_size < 132:
                skipped["too small to be DICOM"] += 1
                continue
            if info.file_size > max_member:
                skipped["file too large"] += 1
                continue
            try:
                path = f"{archive_owner.name}/{n}.dcm"
                with z.open(info) as src, open(path, "wb") as dst:
                    shutil.copyfileobj(src, dst, length=1024*1024)
                ds = pydicom.dcmread(path, force=True, defer_size=1024)
                # Keep the temporary files alive while any indexed dataset is in use.
                ds._archive_owner = archive_owner
                if "PixelData" not in ds or not hasattr(ds, "Rows") or not hasattr(ds, "Columns"):
                    skipped["DICOM without image pixels (DICOMDIR, report ...)"] += 1
                    continue
                out.append((info.filename, ds))
            except Exception:
                skipped["not a DICOM file"] += 1
            if progress and n % 20 == 0:
                progress(n / max(1, len(infos)))
    return out, skipped

def quantitative_series(ds):
    if getattr(ds,"_diffusion_family","") in ("ADC","UNCLASSIFIED"):return True
    text = " ".join([str(getattr(ds, "SeriesDescription", "")), str(getattr(ds, "ProtocolName", "")), " ".join(str(v) for v in getattr(ds, "ImageType", []))]).upper()
    return bool(re.search(r"\b(?:ADC|FA|CBF|CBV|MTT|TTP|PARAMETRIC|PERFUSION|PHASE)\b|T[12]\s*\*?\s*MAP|R[12]\s*\*?\s*MAP", text)
                or hasattr(ds, "RealWorldValueMappingSequence")
                or str(getattr(ds, "ComplexImageComponent", "")).upper() in ("PHASE", "REAL", "IMAGINARY"))


def adaptive_series_reason(s):
    for ds in s["items"]:
        if str(getattr(ds, "Modality", "")).upper() != "MR":
            return "Enhancement is available for magnitude MR images only"
        if str(getattr(ds, "PhotometricInterpretation", "")).upper() not in ("MONOCHROME1", "MONOCHROME2"):
            return "Unsupported pixel presentation for MRI enhancement"
        if min(int(getattr(ds, "Rows", 0)), int(getattr(ds, "Columns", 0))) < 16:
            return "Image matrix too small for adaptive noise estimation"
        if quantitative_series(ds):
            return "Quantitative or phase series: original pixels retained"
    if cine_series(s):
        return "Dynamic/cine series: original pixels retained"
    return None



def station_signature(s):
    """Strict acquisition gate: missing timing or ambiguous derived data are unsupported."""
    ds=s["items"][0]
    if adaptive_series_reason(s):
        return None
    timing=[_first(getattr(ds,key,None)) for key in ("EchoTime","RepetitionTime")]
    if any(v is None or not np.isfinite(v) or v<=0 for v in timing):
        return None
    types=" ".join(str(v).upper() for v in getattr(ds,"ImageType",[]))
    desc=str(getattr(ds,"SeriesDescription","")).upper()
    if any(t in types+" "+desc for t in ("DERIVED","LOCALIZER","SCOUT","SCANO")):
        return None
    # Suppression variants must not be mixed even if TR/TE happen to agree.
    suppression="STIR" if "STIR" in desc else "FS" if re.search(r"FAT|SPAIR|SPIR|(?:^|[^A-Z])FS(?:$|[^A-Z])|T[12]FS|PDFS",desc) else "NONE"
    ti=_first(getattr(ds,"InversionTime",None),0) or 0
    return dict(te=timing[0],tr=timing[1],ti=ti,suppression=suppression,
                sequence=str(getattr(ds,"ScanningSequence","")),
                component=("WATER" if "WATER" in desc else "FAT" if "FAT ONLY" in desc else "OTHER"),
                contrast=bool(re.search(r"POST|GAD|C[+]",desc)),
                agent=str(getattr(ds,"ContrastBolusAgent","")))


def station_compatible(a,b):
    if not a or not b:return False
    if any(a[k]!=b[k] for k in ("suppression","sequence","component","contrast","agent")):return False
    return all(abs(a[k]-b[k])<=max(1,frac*min(a[k],b[k]))
               for k,frac in (("te",.1),("tr",.2),("ti",.1)))


def station_pair_ratio(a,b):
    """Estimate target/reference gain using coplanar DICOM physical overlap only.

    No deformation or anatomical synthesis. Disagreement rejects a pair rather
    than manufacturing correspondence. Source (o) frames verify alignment; active display frames determine gain.
    """
    if a.get("streamed") or b.get("streamed") or not station_compatible(a.get("stationSignature"),b.get("stationSignature")):
        return None,"incompatible or unsupported acquisition"
    ratios=[];supports=[]
    indices=np.unique(np.linspace(0,len(a["items"])-1,min(5,len(a["items"]))).astype(int))
    used=set()
    for i in indices:
        ga=a["geometry"][i]
        if not ga:continue
        candidates=[]
        for j,gb in enumerate(b["geometry"]):
            if not gb or gb["ref"]!=ga["ref"] or gb["study"]!=ga["study"]:continue
            if abs(np.dot(ga["normal"],gb["normal"]))<.9999:continue
            distance=abs(np.dot(np.subtract(gb["origin"],ga["origin"]),ga["normal"]))
            if distance<=.75:candidates.append((distance,j))
        if not candidates:continue
        _,j=min(candidates)
        if j in used:continue
        gb=b["geometry"][j]
        ya,xa=np.mgrid[2:a["rows"]-2:3,2:a["cols"]-2:3]
        points=(np.asarray(ga["origin"])+xa[...,None]*np.asarray(ga["row"])*ga["spacing"][1]
                +ya[...,None]*np.asarray(ga["col"])*ga["spacing"][0])
        delta=points-np.asarray(gb["origin"])
        xb=delta@np.asarray(gb["row"])/gb["spacing"][1]
        yb=delta@np.asarray(gb["col"])/gb["spacing"][0]
        inside=(xb>=2)&(xb<b["cols"]-3)&(yb>=2)&(yb<b["rows"]-3)
        if inside.sum()<100:continue
        fa=unpack_frame(a["items"][i]["o"],a["rows"],a["cols"],a["off"],a["scale"])
        fb=unpack_frame(b["items"][j]["o"],b["rows"],b["cols"],b["off"],b["scale"])
        if min(fa.min(),fb.min())<0:continue
        va=fa[ya,xa];vb=ndi.map_coordinates(fb,[yb,xb],order=1,mode="nearest")
        tissue=inside&(va>.1*np.percentile(fa,99))&(vb>.1*np.percentile(fb,99))
        if tissue.sum()<100:continue
        x=va[tissue];y=vb[tissue]
        if min(np.std(x)/np.mean(x),np.std(y)/np.mean(y))<.08:continue
        if np.corrcoef(x,y)[0,1]<.97:continue
        # Verify correspondence on source pixels, then match the active processed copies.
        if "e" in a["items"][i]:
            fa=unpack_frame(a["items"][i]["e"],a["rows"],a["cols"],a["off"],a["scale"])
            x=fa[ya,xa][tissue]
        if "e" in b["items"][j]:
            fb=unpack_frame(b["items"][j]["e"],b["rows"],b["cols"],b["off"],b["scale"])
            y=ndi.map_coordinates(fb,[yb,xb],order=1,mode="nearest")[tissue]
        if np.any(x<=0) or np.any(y<=0):continue
        logs=np.log(x/y); center=float(np.median(logs))
        if np.median(np.abs(logs-center))>.10:continue
        ratios.append(center);supports.append(int(tissue.sum()));used.add(j)
    if len(ratios)<2:return None,"need at least two aligned overlapping slices with matching anatomy"
    center=float(np.median(ratios))
    if max(abs(np.asarray(ratios)-center))>.12:return None,"overlap ratios disagree across slices"
    if not np.log(2/3)<=center<=np.log(1.5):return None,"required gain exceeds conservative limits"
    return float(np.exp(center)),f"{len(ratios)} overlapping slices, {sum(supports)} tissue samples"


def match_station_payloads(payloads,selected,reference):
    """Modify display copies only; reference is fixed, disconnected stations skipped."""
    import copy
    out=copy.deepcopy(payloads);logs=[];gains={reference:1.0};edges={}
    for n,i in enumerate(selected):
        for j in selected[n+1:]:
            ratio,reason=station_pair_ratio(payloads[i],payloads[j])
            if ratio is not None:edges[i,j]=ratio
            else:logs.append(f"{i+1} ↔ {j+1}: skipped — {reason}")
    # Propagate only connected, cycle-consistent gains; never clip a required correction.
    for _ in selected:
        for (i,j),ratio in edges.items():
            if i in gains and j not in gains:gains[j]=gains[i]*ratio
            elif j in gains and i not in gains:gains[i]=gains[j]/ratio
    if any(abs(np.log(gains[j]/gains[i]/r))>.10 for (i,j),r in edges.items() if i in gains and j in gains):
        return payloads,["No matching applied: overlapping stations have inconsistent gain estimates."]
    if any(not 2/3<=v<=1.5 for v in gains.values()):
        return payloads,["No matching applied: cumulative correction exceeds conservative limits."]
    windows=copy.deepcopy(payloads[reference]["wl"])
    for i in selected:
        if i not in gains:
            logs.append(f"Station {i+1}: unchanged — no reliable overlap path to reference")
            continue
        if len(gains)<2:continue
        p=out[i];gain=gains[i]
        originals=[unpack_frame(it["o"],p["rows"],p["cols"],p["off"],p["scale"]) for it in p["items"]]
        display=[unpack_frame(it.get("e",it["o"]),p["rows"],p["cols"],p["off"],p["scale"])*gain for it in p["items"]]
        p.update(pack_series(originals,display));p["hasEnh"]=True;p["wl"]=copy.deepcopy(windows)
        p["presentation"]=dict(default="auto",field=None,base=0)
        p["processing"]=dict(p["processing"],engine=p["processing"]["engine"]+" + Station Match",
                              applied=len(display),frames=["station matched"]*len(display))
        # Original must restore this station's own source window, not the shared reference.
        p["stationOriginalWL"]=payloads[i]["wl"]
        p["stationMatch"]=dict(gain=round(gain,5),reference=reference+1)
        p["memoryId"] += "|station:"+str(reference)+":"+str(round(gain,5))
        logs.append(f"Station {i+1}: display gain {gain:.3f}×; reference station {reference+1}")
    return out,logs



def adc_mapping(ds):
    """Explicit linear stored-pixel -> mm²/s mapping only; no magnitude-based unit guessing."""
    maps=[]
    for item in getattr(ds,"RealWorldValueMappingSequence",[]):
        units=getattr(item,"MeasurementUnitsCodeSequence",[])
        if len(units)!=1 or str(getattr(units[0],"CodingSchemeDesignator",""))!="UCUM":continue
        unit=str(getattr(units[0],"CodeValue",""))
        factor={"mm2/s":1.0,"um2/s":1e-6,"10*-6.mm2/s":1e-6}.get(unit)
        slope=_first(getattr(item,"RealWorldValueSlope",None));intercept=_first(getattr(item,"RealWorldValueIntercept",None))
        modality_slope=_first(getattr(ds,"RescaleSlope",None),1);modality_intercept=_first(getattr(ds,"RescaleIntercept",None),0)
        if factor is None or slope is None or intercept is None or not modality_slope:continue
        a=slope*factor/modality_slope;b=intercept*factor-modality_intercept*a
        if not np.isfinite([a,b]).all() or a<=0:continue
        maps.append(dict(slope=a,intercept=b,storedLo=_first(getattr(item,"RealWorldValueFirstValueMapped",None)),storedHi=_first(getattr(item,"RealWorldValueLastValueMapped",None)),modalitySlope=modality_slope,modalityIntercept=modality_intercept))
    return maps[0] if len(maps)==1 else None


def diffusion_payload_metadata(s):
    ds=s["items"][0];family=s.get("diffusion_family","")
    body=" ".join(str(getattr(ds,k,"")) for k in ("BodyPartExamined","SeriesDescription","ProtocolName")).upper()
    return dict(family=family,bvalue=s.get("bvalue"),source=s.get("source_uid",s["uid"]),brain=bool(re.search(r"BRAIN|HEAD|CEREBR",body)),
                mappings=[adc_mapping(d) for d in s["items"]] if family=="ADC" else [],
                acquisition=str(getattr(ds,"AcquisitionTime","") or ""))


def same_diffusion_grid(a,b):
    if not a or not b or a["ref"]!=b["ref"] or a["study"]!=b["study"]:return False
    return (np.max(np.abs(np.asarray(a["origin"])-b["origin"]))<=.1
            and np.max(np.abs(np.asarray(a["row"])-b["row"]))<1e-4
            and np.max(np.abs(np.asarray(a["col"])-b["col"]))<1e-4
            and np.max(np.abs(np.asarray(a["spacing"])-b["spacing"]))<1e-3)


def pair_diffusion_payloads(payloads):
    """Require unambiguous ADC series with a one-to-one matching physical grid."""
    for i,dwi in enumerate(payloads):
        meta=dwi.get("diffusion",{})
        if meta.get("family")!="DWI":continue
        matches=[]
        for j,adc in enumerate(payloads):
            am=adc.get("diffusion",{})
            if am.get("family")!="ADC" or (adc["rows"],adc["cols"])!=(dwi["rows"],dwi["cols"]):continue
            mapping=[]
            for g in dwi["geometry"]:
                candidates=[k for k,h in enumerate(adc["geometry"]) if same_diffusion_grid(g,h)]
                if len(candidates)!=1:break
                mapping.append(candidates[0])
            if len(mapping)==len(dwi["items"]) and len(set(mapping))==len(mapping):matches.append((j,mapping))
        # Prefer maps exported inside the same parent series, otherwise require uniqueness.
        preferred=[v for v in matches if payloads[v[0]]["diffusion"]["source"]==meta.get("source")]
        options=preferred or matches
        if len(options)==1:
            j,mapping=options[0];dwi["diffusionPair"]=dict(adc=j,frames=mapping,status="Geometry-matched; verify acquisition and anatomy")
        else:dwi["diffusionPair"]=dict(adc=None,frames=[],status="Ambiguous ADC series" if options else "No ADC with an unambiguous matching physical grid")


def restricted_candidates(dwi,adc,mapping,confirm_brain=False):
    """Untrained research baseline. Thresholds are engineering choices, not validated diagnostic cutoffs.

    No probability/confidence or negative stroke result is produced. Never uses
    enhanced pixels. Physical alignment alone cannot exclude patient motion.
    """
    meta=dwi.get("diffusion",{});am=adc.get("diffusion",{})
    def skip(reason):return dict(status="skipped",reason=reason,frames=[],count=0)
    if not (confirm_brain or meta.get("brain")):return skip("Brain study confirmation is required")
    if meta.get("family")!="DWI" or am.get("family")!="ADC":return skip("DWI and ADC are required")
    if meta.get("bvalue") is None or not 700<=meta["bvalue"]<=1500:return skip("A documented high b-value between 700 and 1500 s/mm² is required")
    if dwi.get("streamed") or adc.get("streamed"):return skip("Streamed series are outside this research processing path")
    if len(mapping)!=len(dwi["items"]):return skip("Incomplete DWI/ADC pairing")
    if any(k>=len(am.get("mappings",[])) or am["mappings"][k] is None for k in mapping):return skip("Explicit ADC units/scaling in DICOM Real World Value Mapping are required")
    rows,cols=dwi["rows"],dwi["cols"];masks=[];total=0;points=0
    for n,k in enumerate(mapping):
        if not same_diffusion_grid(dwi["geometry"][n],adc["geometry"][k]):return skip("Images do not share the same physical grid")
        d=unpack_frame(dwi["items"][n]["o"],rows,cols,dwi["off"],dwi["scale"])
        a=unpack_frame(adc["items"][k]["o"],rows,cols,adc["off"],adc["scale"])
        mp=am["mappings"][k];stored=(a-mp["modalityIntercept"])/mp["modalitySlope"]
        adc_values=a*mp["slope"]+mp["intercept"]
        valid=np.isfinite(d)&np.isfinite(adc_values)&(d>0)&(adc_values>0)&(adc_values<.0025)
        if mp["storedLo"] is not None:valid &= stored>=mp["storedLo"]-1
        if mp["storedHi"] is not None:valid &= stored<=mp["storedHi"]+1
        foreground=valid&(d>.1*np.percentile(d,99.5))
        if foreground.sum()<200:masks.append([]);continue
        median=float(np.median(d[foreground]));mad=float(np.median(np.abs(d[foreground]-median)))*1.4826
        if mad<=0:masks.append([]);continue
        normal_adc=float(np.median(adc_values[foreground]))
        candidate=foreground&(d>median+2.5*mad)&(adc_values<.00065)&(adc_values<.8*normal_adc)
        labels,count=ndi.label(candidate);sizes=np.bincount(labels.ravel());keep=sizes>=max(3,int(np.ceil(2.0/(dwi["spacing"][0]*dwi["spacing"][1]))));keep[0]=False
        candidate=keep[labels];total+=int(keep.sum())
        outline=candidate&~ndi.binary_erosion(candidate);flat=np.flatnonzero(outline);points+=len(flat)
        if points>100000:return skip("Candidate outline exceeds the research overlay limit")
        runs=[]
        for y in np.unique(flat//cols):
            xs=np.flatnonzero(outline[y]);start=last=int(xs[0])
            for x in xs[1:]:
                if x!=last+1:runs.append([int(y),start,last-start+1]);start=int(x)
                last=int(x)
            runs.append([int(y),start,last-start+1])
        masks.append(runs)
    return dict(status="processed",reason="Untrained rule-based research candidates; false positives and missed lesions expected. Review DWI, ADC and other sequences. No candidates does not exclude infarction.",frames=masks,count=total)


def clinical_display_windows(frames,ds):
    """Linear, series-relative MRI display aids, never lesion or vessel detection."""
    if not frames or str(getattr(ds,"Modality","")).upper()!="MR" or quantitative_series(ds):return {}
    samples=[]
    for k in np.unique(np.linspace(0,len(frames)-1,min(5,len(frames))).astype(int)):
        a=np.asarray(frames[k]).ravel()
        samples.append(a[::max(1,len(a)//4096)])
    values=np.concatenate(samples);values=values[np.isfinite(values)]
    if len(values)<100 or values.min()<0:return {}
    high=float(np.percentile(values,99.8));tissue=values[values>high*.08]
    if len(tissue)<100 or high<=0:return {}
    q=np.percentile(tissue,[10,25,40,60,98,99.5,99.8])
    result={"angio":[float(q[3]),float(q[6])],"vessels":[float(q[2]),float(q[5])]}
    desc=str(getattr(ds,"SeriesDescription","")).upper()
    bvalue=_first(getattr(ds,"DiffusionBValue",None),0) or 0
    if bvalue>0 or re.search(r"DWI|DIFF|TRACE",desc):result["dwi"]=[float(q[0]),float(q[4])]
    return {k:v for k,v in result.items() if v[1]>v[0]}



def volume_support(s):
    """Acquisition-level volume gates complement client-side physical-grid validation."""
    if cine_series(s):return dict(reason="Dynamic/cine or unsupported multi-frame data cannot form a static spatial volume.")
    if any(str(getattr(d,"PhotometricInterpretation","")).upper() not in ("MONOCHROME1","MONOCHROME2") for d in s["items"]):return dict(reason="Scalar monochrome pixels are required.")
    echoes={round(float(v),3) for d in s["items"] if (v:=_first(getattr(d,"EchoTime",None))) is not None}
    if len(echoes)>1:return dict(reason="Mixed echo times: choose a single-echo stack.")
    bvalues={round(float(v),1) for d in s["items"] if (v:=_first(getattr(d,"DiffusionBValue",None))) is not None}
    if len(bvalues)>1:return dict(reason="Mixed diffusion b-values: choose one separated DWI stack.")
    if any("MOSAIC" in str(getattr(d,"ImageType","")).upper() for d in s["items"]):return dict(reason="Vendor mosaic images need unpacking before reconstruction.")
    thickness=[_first(getattr(d,"SliceThickness",None)) for d in s["items"]]
    thickness=[v for v in thickness if v is not None and np.isfinite(v) and v>0]
    return dict(reason=None,sliceThickness=float(np.median(thickness)) if thickness else None)


def build_payload_series(s, enhance, params, progress=None, force_stream=False, enhance_requested=None):
    streamed = force_stream or cine_series(s) or payload_estimate(s, enhance) > 24*1024*1024
    if payload_estimate(s, False) > 2*1024*1024*1024:
        raise RuntimeError("This series exceeds the current decoded-workload limit. It was not partially loaded.")
    frames, errors = [], []
    if streamed:
        packed, info, source_min, source_max = stream_pack_series(s, progress)
    else:
        for index, ds in enumerate(s["items"], 1):
            try:
                frames += modality_frames(ds)
            except Exception as exc:
                errors.append((index, str(exc)))
        if errors:
            index, reason = errors[0]
            raise RuntimeError(f"{len(errors)} instances could not be decoded (first: {index}). Series not displayed to avoid an incomplete stack. {reason}")
        if not frames: raise RuntimeError("Series contains no image frames.")
        info = series_info(frames)
        source_min = float(min(f.min() for f in frames)); source_max = float(max(f.max() for f in frames))
    a = s["items"][0]
    sp = _floats(getattr(a, "PixelSpacing", None) or [], 2) or [1.0, 1.0]
    enh = None
    adaptive = params.get("algorithm") == "adaptive"
    neural = params.get("algorithm") == "neural"
    frame_states = []
    reason = adaptive_series_reason(s)
    if not enhance:
        reason = "Original pixels: workspace processing limit" if enhance_requested else "Enhancement disabled"
    elif streamed:
        reason = reason or "Original pixels: streamed-series processing limit"
    elif (adaptive or neural or params.get("signal_balance",0)>0) and source_min < 0:
        reason = "Signed intensity data: original pixels retained"
    balance_gain = None
    balance_status = None
    if enhance and not streamed and not reason and params.get("signal_balance",0)>0:
        balance_gain,balance_status=signal_balance_gain(frames,params["signal_balance"])
    if enhance and not streamed and not reason:
        enh = []
        for k in range(len(frames)):
            if neural:
                processed,status=neural_restore_frame(frames[k],params.get("neural_strength",.25))
                enh.append(processed)
                frame_states.append("processed" if status["status"]=="processed" else status["status"])
            elif adaptive:
                processed, status = denoise_magnitude(frames[k], params.get("strength", "gentle"),
                                                     restore_detail=params.get("restore_detail", True))
                frame_states.append("processed" if status["status"] == "processed" else "original: insufficient noise support")
                enh.append(processed)
            else:
                processed=enhance_frame(frames, k, info, params)
                enh.append(processed)
                frame_states.append("processed" if not np.array_equal(processed,frames[k]) else "original: insufficient noise support or processing off")
            if balance_gain is not None:
                enh[-1] = (enh[-1]*balance_gain).astype(np.float32)
                if not np.array_equal(enh[-1],frames[k]):
                    frame_states[-1] = "processed · Signal Balance"
            if progress:
                progress((k + 1) / len(frames))
        if not any(state == "processed" for state in frame_states):
            enh = None
            reason = "Original pixels: insufficient local noise support"
    applied = sum(state == "processed" for state in frame_states)
    processing = dict(engine="Neural Restore v0.2 · experimental" if neural else "Adaptive texture MRI v0.4 · experimental" if adaptive else "Texture-preserving enhancement",
                      reason=reason, applied=applied, frames=frame_states)
    if balance_gain is not None:
        processing["engine"] += " + Signal Balance"
        processing["signal_balance"] = balance_status
    # Single-frame geometry only; do not invent positions for enhanced multi-frame objects.
    geometry = []
    for ds in s["items"]:
        ipp = _floats(getattr(ds, "ImagePositionPatient", None) or [], 3)
        iop = _floats(getattr(ds, "ImageOrientationPatient", None) or [], 6)
        spacing = _floats(getattr(ds, "PixelSpacing", None) or [], 2)
        ref = str(getattr(ds, "FrameOfReferenceUID", "") or "")
        study = str(getattr(ds, "StudyInstanceUID", "") or "")
        valid = (ipp and iop and spacing and ref and study
                 and int(getattr(ds, "NumberOfFrames", 1) or 1) == 1
                 and np.isfinite(ipp + iop + spacing).all()
                 and min(spacing) > 0)
        if valid:
            r, c = np.array(iop[:3]), np.array(iop[3:])
            valid = abs(np.linalg.norm(r)-1) < .001 and abs(np.linalg.norm(c)-1) < .001 and abs(np.dot(r,c)) < .001
        geometry.append(dict(origin=ipp, row=iop[:3], col=iop[3:], normal=np.cross(r,c).tolist(),
                             spacing=spacing, ref=ref, study=study) if valid else None)
    count = len(packed["items"]) if streamed else len(frames)
    if len(geometry) != count:
        geometry = [None] * count
    if not streamed:
        packed = pack_series(frames, enh)
    pos = [slice_position(d, s["normal"]) for d in s["items"]]
    if len(pos) != count or any(p is None for p in pos):
        pos = [float(i) for i in range(count)]
    wc = _first(getattr(a, "WindowCenter", None)); ww = _first(getattr(a, "WindowWidth", None))
    slope = _first(getattr(a, "RescaleSlope", None), 1.0) or 1.0
    icpt = _first(getattr(a, "RescaleIntercept", None), 0.0) or 0.0
    # DICOM LINEAR uses center-.5 and width-1 after modality scaling.
    dicom_wl = [wc-.5-(ww-1)/2, wc-.5+(ww-1)/2] if (wc is not None and ww is not None and ww > 1 and np.isfinite([wc, ww]).all()) else None
    description = str(getattr(a, "SeriesDescription", "") or getattr(a, "ProtocolName", "") or "").upper()
    quantitative = quantitative_series(a) or str(getattr(a, "Modality", "")).upper() != "MR"
    orientations = {tuple(np.round(_floats(getattr(d, "ImageOrientationPatient", None) or [], 6) or [], 4)) for d in s["items"]}
    balanced_default = not quantitative and not cine_series(s)
    field = info.get("field") if balanced_default and len(orientations) == 1 and () not in orientations and params.get("shading", 0) == 0 else None
    return dict(volumeSupport=volume_support(s), diffusion=diffusion_payload_metadata(s), stationSignature=station_signature(s), title=s["label"], modality=str(getattr(a, "Modality", "")).upper(), plane=plane_name(s["normal"]), rows=s["rows"], cols=s["cols"],
                spacing=[float(sp[0]), float(sp[1])], memoryId=hashlib.sha256(f"{s['uid']}|{s['desc']}|{s['rows']}|{s['cols']}".encode()).hexdigest(), spacingKnown=bool(_floats(getattr(a, "PixelSpacing", None) or [], 2)), thickness=_first(getattr(a, "SliceThickness", None)), geometry=geometry, sequence=str(getattr(a, "SeriesDescription", "") or getattr(a, "ProtocolName", "") or ""),
                invert=str(getattr(a, "PhotometricInterpretation", "")).upper() == "MONOCHROME1",
                pos=pos, hasEnh=bool(enh), processing=processing, streamed=streamed, snr=round(info["snr"], 1), sigma=info["sigma"],
                presentation=dict(default="dicom" if dicom_wl else "auto", field=field, base=info["lo"]),
                wl=dict(**clinical_display_windows(frames,a), balanced=dicom_wl or [info["lo"], info["hi"]], auto=[info["lo"], info["hi"]], dicom=dicom_wl, full=[source_min, source_max]),
                **packed)

