def build_empty_workspace():
    theme = VIEWER_HTML.split("</style>")[0] + "</style>"
    theme = theme.replace("__COLS__", "2").replace("__PANEL_H__", "300")
    icon = '<svg viewBox="0 0 48 48"><rect x="5" y="5" width="38" height="38" rx="3"/><path d="M16 24h16M24 16v16"/></svg>'
    tools = '<div id="bar"><div class="brand-tag">IMAGE TOOLS</div>'
    for label in []:
        tools += f'<button disabled>{label}</button>'
    tools += '<span style="margin-left:auto;color:#6b8198;font-size:10px">2 × 2 workspace · Awaiting study</span></div>'
    rail = '<nav id="series-rail"><div class="rail-heading">LOADED SERIES</div><div class="rail-empty">+</div><div class="rail-hint">No series available.<br>Import a study using the panel on the left.</div></nav>'
    cells = ''
    for i in range(4):
        title = "Ready for your next study" if i == 0 else "Viewport available"
        hint = "Open a DICOM ZIP from the study browser" if i == 0 else "Selected series will appear here"
        cells += f'<div class="panel"><div class="empty-canvas"><div class="corner">VIEWPORT {i+1:02d} / NO SERIES</div><div class="center">{icon}<b>{title}</b>{hint}</div><div class="bottom">W — &nbsp; L — &nbsp; / &nbsp; IMAGE —</div></div></div>'
    icon_section = VIEWER_HTML.split("const icons={",1)[1].split("};",1)[0]
    paths = dict(re.findall(r"(\w+):'([^']*)'",icon_section))
    def placeholder(name,key):
        svg='<svg viewBox="0 0 24 24" aria-hidden="true">'+paths.get(key,"")+'</svg>'
        return f'<button class="tool-button" disabled title="{name} — load a study to use this tool" aria-label="{name}">{svg}</button>'
    tool_rail='<nav id="tool-rail" aria-label="Image tools"><div class="tool-scroll">'+''.join(placeholder(name,key) for name,key in [("Window / level","wl"),("Pan","pan"),("Zoom","zoom"),("3D pointer","pointer3d"),("Rotate image","rotate"),("Flip horizontal","flipH"),("Flip vertical","flipV"),("Distance","dist"),("Angle","angle"),("Rectangle ROI","roi"),("Ellipse ROI","ellipse"),("Arrow annotation","arrow"),("Text annotation","text")])+'</div><div class="tool-pinned">'+''.join(placeholder(name,key) for name,key in [("MPR","mpr"),("MIP","mip"),("MinIP","minip"),("Average projection","average"),("VR","vr"),("Stitch / Compose","stitch")])+'</div></nav>'

    fit_script = '<script>' + VIEWER_HTML.split('<script>')[1].split('const P=')[0] + '</script>'
    tools=tools.replace('<div class="brand-tag">IMAGE TOOLS</div>', '<button data-open-workflow title="Open study — upload a DICOM ZIP or change study and processing settings" aria-label="Open study"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M3 6h7l2 3h9v11H3ZM3 9V4h7l2 2h8v3"/></svg></button>' )
    header=WORKSTATION_HEADER_HTML.replace('>Study <span>', '>No study <span>').replace('MRI · Image review','Open a DICOM ZIP to begin').replace('<div id="bar"><div class="brand-tag">IMAGE TOOLS</div></div>',tools)
    header=re.sub(r'<button data-layout=', '<button disabled data-layout=',header)
    tool_rail=re.sub(r'<div class="tool-scroll">.*?</div>', '',tool_rail)
    tool_rail=re.sub(r'(<button[^>]+aria-label="([^"]+)"[^>]*>.*?</svg>)(</button>)',lambda m:m[1]+'<span>'+escape(m[2].replace(' projection','').replace(' / Compose',''))+'</span>'+m[3],tool_rail)
    return theme + header + '<div class="workspace">' + tool_rail + rail + '<section class="viewer-stage"><div id="grid">' + cells + '</div></section>' + INSPECTOR_HTML + '</div><div class="workspace-footer"><span>No image data loaded</span><span>Measurements · Linked review · Original comparison</span></div>' + fit_script


def build_viewer_html(series_payloads, patient_text=None, panel_height=360, study_key=None):
    n = len(series_payloads)
    cols = 2 if n >= 2 else 1
    payload = dict(series=series_payloads, patient=patient_text, studyKey=study_key, viewerBuild=APP_BUILD)
    data = json.dumps(payload, separators=(",", ":")).replace("</", r"<\/")
    html = (VIEWER_HTML.replace("__PAYLOAD__", data).replace("__COLS__", str(cols)).replace("__PANEL_H__", str(panel_height)))
    rows = -(-n // cols)
    return html, 760

